mapper.sql:
WHERE R.DEL_YN = 'N'
 AND R.RESERVATION_STTS_CD = #{status} 
 AND R.CHECK_IN_DATE >= #{startDate} 
   AND R.CHECK_IN_DATE <= #{endDate} 

    AND ( H.HOUSE_NM LIKE CONCAT('%', #{keyword}, '%')
       OR R.ORDER_NO LIKE CONCAT('%', #{keyword}, '%')
       OR EXISTS (SELECT 1 FROM RESERVATION_GUEST GK
                   WHERE GK.RESERVATION_SN = R.RESERVATION_SN
                     AND GK.DEL_YN = 'N'
                     AND GK.GUEST_NM LIKE CONCAT('%', #{keyword}, '%')) )

mapper.select:
SELECT 


 ORDER BY R.RESERVATION_SN DESC
 LIMIT #{limit} OFFSET #{offset}
